import fs from "node:fs";
import path from "node:path";
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Main address is https://cascadecharterbus.com (no www); trailing-slash URLs everywhere.
  trailingSlash: true,
  poweredByHeader: false,
  reactStrictMode: true,
  images: {
    formats: ["image/avif", "image/webp"],
  },
  // Redirect/410 rules are generated by scripts/build-redirects into `redirects.json`
  // and imported here (brief Sections 9.1 and 10). Populated in Phase 6.
  async redirects() {
    const base = [
      // One main address: every www -> apex (https handled by host)
      { source: "/:path*", has: [{ type: "host", value: "www.cascadecharterbus.com" }], destination: "https://cascadecharterbus.com/:path*", permanent: true },
    ];
    let removed: Array<{ source: string; destination: string; permanent: boolean }> = [];
    try {
      removed = JSON.parse(
        await fs.promises.readFile(
          path.join(process.cwd(), "redirects-generated.json"),
          "utf8"
        )
      );
    } catch {
      removed = [];
    }
    const all: Array<{ source: string; destination: string; permanent: boolean }> = [...base, ...removed];
    return all as any;
  },
};

export default nextConfig;
